  "content": "1|import {
2|  getDesignerDraft,
3|  getDesignerDraftVersion,
4|  listDesignerDrafts,
5|  listDesignerDraftVersions,
6|} from '../domain/component-designer/drafts';
7|import {
8|  createDesignerComponentStagingPreview,
9|  getDesignerPublishDiff,
10|  getDesignerPublishState,
11|  loadDesignerStagingPreviewPayload,
12|  publishDesignerComponent,
13|  rollbackDesignerPublishedVersion,
14|} from './component-designer/publishCoordinator.service';
15|import {
16|  deleteDesignerDraft,
17|  duplicateDesignerDraft,
18|  duplicateShellLayoutDraft,
19|  saveDesignerDraft,
20|} from './component-designer/draftCoordinator.service';
21|import { listDesignerPublishedVersionSummaries } from '../domain/component-designer/publishIo';
22|import { parsePinnedDesignerLoaderRef } from '../../domain/component-designer/publishLoaderRef';
23|import { DESIGNER_PALETTE } from '../../domain/component-designer/catalog';
24|import { buildReusablePaletteItems } from '../../domain/component-designer/reusablePalette';
25|import { syncCodeToCanvas } from '../../domain/component-designer/codegen';
26|import { collectBindingDependencies, resolveRuntimeBinding } from '../../domain/component-designer/runtime';
27|import { writeDesignerPreviewLog } from '../domain/component-designer/storage';
28|import { normalizeDesignerViewport } from '../../domain/component-designer/state';
29|import type { DesignerBindingDefinition, DesignerDocument, DesignerWorkspacePrefs } from '../../domain/component-designer/types';
30|import { validateDesignerDocument } from '../../domain/component-designer/validation';
31|import { HttpError } from '../errors/HttpError';
32|import {
33|  getBuiltInComponentRecord,
34|  getBuiltInComponentRecordByName,
35|  isBuiltInComponentId,
36|  mergeComponentsCatalog,
37|} from '../../features/component-designer/layout-presets/builtInComponents';
38|import { isSystemManagedShellLayoutDraft } from '../../features/component-designer/lib/shellDesignerDraft';
39|import {
40|  filterDraftsShadowedByInstalledPackageUi,
41|  getInstalledPackageUiDraftRecord,
42|  isPackageUiCatalogId,
43|  listInstalledPackageUiCatalogSummaries,
44|  updateInstalledPackageUiDraftRecord,
45|} from '../services/package-runtime/packageUiCatalog.service';
46|
47|export type ComponentDesignerServiceDeps = {
48|  serverPort: number;
49|};
50|
51|export class ComponentDesignerService {
52|  constructor(private readonly deps: ComponentDesignerServiceDeps) {}
53|
54|  listDrafts() {
55|    const items = listDesignerDrafts().filter((item) => !isSystemManagedShellLayoutDraft(item));
56|    const packageItems = listInstalledPackageUiCatalogSummaries();
57|    const visibleItems = filterDraftsShadowedByInstalledPackageUi(items);
58|    return { body: { success: true as const, items: mergeComponentsCatalog([...visibleItems, ...packageItems]) } };
59|  }
60|
61|  createDraft(payload: Record<string, unknown>, actor: string) {
62|    const duplicateFromId = typeof payload.duplicateFromId === 'string' ? payload.duplicateFromId : null;
63|
64|    if (duplicateFromId) {
65|      const draft = duplicateDesignerDraft(
66|        duplicateFromId,
67|        typeof payload.name === 'string' ? payload.name : undefined,
68|        actor,
69|        typeof payload.folder === 'string' ? payload.folder : undefined,
70|      );
71|      return { statusCode: 201, body: { success: true as const, draft } };
72|    }
73|
74|    const draft = saveDesignerDraft({
75|      id: typeof payload.id === 'string' ? payload.id : undefined,
76|      name: typeof payload.name === 'string' ? payload.name : 'Untitled Component',
77|      folder: typeof payload.folder === 'string' ? payload.folder : undefined,
78|      document: payload.document as DesignerDocument | undefined,
79|      bindingDefinitions: (payload.bindingDefinitions ?? {}) as Record<string, DesignerBindingDefinition>,
80|      workspace: (() => {
81|        if (typeof payload.workspace !== 'object' || payload.workspace === null) {
82|          return undefined;
83|        }
84|
85|        const workspacePayload = payload.workspace as Record<string, unknown>;
86|        const viewport = normalizeDesignerViewport(workspacePayload.viewport);
87|        return viewport ? { viewport } satisfies DesignerWorkspacePrefs : undefined;
88|      })(),
89|      actor,
90|    });
91|    return { statusCode: 201, body: { success: true as const, draft } };
92|  }
93|
94|  duplicateShellLayout(payload: Record<string, unknown>, actor: string) {
95|    const sourceShellKey = typeof payload.sourceShellKey === 'string' ? payload.sourceShellKey : '';
96|    const targetShellKey = typeof payload.targetShellKey === 'string' ? payload.targetShellKey : '';
97|    if (!sourceShellKey.trim() || !targetShellKey.trim()) {
98|      throw new HttpError(400, 'sourceShellKey and targetShellKey are required.');
99|    }
100|
101|    const draft = duplicateShellLayoutDraft(sourceShellKey, targetShellKey, actor);
102|    return { statusCode: 201, body: { success: true as const, draft } };
103|  }
104|
105|  getDraft(id: string, versionRaw?: string) {
106|    const requestedVersion = versionRaw && versionRaw.trim().length > 0
107|      ? Number(versionRaw)
108|      : undefined;
109|
110|    if (typeof requestedVersion === 'number' && (!Number.isInteger(requestedVersion) || requestedVersion < 1)) {
111|      throw new HttpError(400, 'Invalid version.');
112|    }
113|
114|    const pinnedLoader = parsePinnedDesignerLoaderRef(id);
115|    const versionFromLoader = pinnedLoader.publishedVersion;
116|    const lookupId = versionFromLoader ? pinnedLoader.componentPath : id;
117|
118|    if (typeof requestedVersion === 'number') {
119|      const draft = getDesignerDraftVersion(lookupId, requestedVersion);
120|      if (!draft) {
121|        throw new HttpError(404, 'Version not found.');
122|      }
123|      return { body: { success: true as const, draft } };
124|    }
125|
126|    if (typeof versionFromLoader === 'number') {
127|      const draft = getDesignerDraftVersion(lookupId, versionFromLoader);
128|      if (!draft) {
129|        throw new HttpError(404, 'Version not found.');
130|      }
131|      return { body: { success: true as const, draft } };
132|    }
133|
134|    const storedDraft = getDesignerDraft(lookupId);
135|    if (storedDraft) {
136|      return { body: { success: true as const, draft: storedDraft } };
137|    }
138|
139|    if (isPackageUiCatalogId(id)) {
140|      const packageDraft = getInstalledPackageUiDraftRecord(id);
141|      if (!packageDraft) {
142|        throw new HttpError(404, 'Version not found.');
143|      }
144|      return { body: { success: true as const, draft: packageDraft } };
145|    }
146|
147|    const builtInDraft = getBuiltInComponentRecord(id) ?? getBuiltInComponentRecordByName(id);
148|    if (!builtInDraft) {
149|      throw new HttpError(404, 'Version not found.');
150|    }
151|
152|    return { body: { success: true as const, draft: builtInDraft } };
153|  }
154|
155|  listVersions(id: string) {
156|    const storedDraft = getDesignerDraft(id);
157|    if (!storedDraft) {
158|      return { body: { success: true as const, items: listDesignerDraftVersions(id) } };
159|    }
160|
161|    const publishedVersions = listDesignerPublishedVersionSummaries(storedDraft.id, storedDraft.folder);
162|    if (publishedVersions.length === 0) {
163|      return { body: { success: true as const, items: listDesignerDraftVersions(id) } };
164|    }
165|
166|    return {
167|      body: {
168|        success: true as const,
169|        items: publishedVersions.map((item) => ({
170|          id: storedDraft.id,
171|          name: item.name,
172|          folder: storedDraft.folder,
173|          version: item.version,
174|          createdAt: item.publishedAt,
175|          updatedAt: item.publishedAt,
176|          createdBy: item.publishedBy,
177|          updatedBy: item.publishedBy,
178|        })),
179|      },
180|    };
181|  }
182|
183|  getPublishState(id: string, hasUnsavedChanges = false) {
184|    return { body: { success: true as const, state: getDesignerPublishState(id, { hasUnsavedChanges }) } };
185|  }
186|
187|  getPublishDiff(id: string) {
188|    return { body: { success: true as const, diff: getDesignerPublishDiff(id) } };
189|  }
190|
191|  publishDraft(id: string, actor: string) {
192|    return { body: { success: true as const, state: publishDesignerComponent(id, actor) } };
193|  }
194|
195|  rollbackDraft(id: string, version: number, actor: string) {
196|    return { body: { success: true as const, state: rollbackDesignerPublishedVersion(id, version, actor) } };
197|  }
198|
199|  createStagingPreview(id: string) {
200|    return { statusCode: 201, body: { success: true as const, ...createDesignerComponentStagingPreview(id) } };
201|  }
202|
203|  getStagingPreview(token: string) {
204|    const payload = loadDesignerStagingPreviewPayload(token);
205|    return {
206|      body: {
207|        success: true as const,
208|        preview: {
209|          componentPath: payload.componentPath,
210|          document: payload.document,
211|          bindingDefinitions: payload.bindingDefinitions,
212|          expiresAt: payload.expiresAt,
213|        },
214|      },
215|    };
216|  }
217|
218|  updateDraft(id: string, payload: Record<string, unknown>, actor: string) {
219|    if (isBuiltInComponentId(id)) {
220|      throw new HttpError(400, 'Built-in components cannot be modified.');
221|    }
222|
223|    if (isPackageUiCatalogId(id)) {
224|      const hasDocumentPayload = typeof payload.document === 'object' && payload.document !== null;
225|      const hasBindingsPayload = typeof payload.bindingDefinitions === 'object' && payload.bindingDefinitions !== null;
226|      if (!hasDocumentPayload && !hasBindingsPayload) {
227|        throw new HttpError(400, 'Package UI components can only be updated with document or binding changes.');
228|      }
229|
230|      const result = updateInstalledPackageUiDraftRecord(id, {
231|        document: hasDocumentPayload ? payload.document as DesignerDocument : undefined,
232|        bindingDefinitions: hasBindingsPayload
233|          ? payload.bindingDefinitions as Record<string, DesignerBindingDefinition>
234|          : undefined,
235|      });
236|      if (!result.ok) {
237|        throw new HttpError(400, result.error);
238|      }
239|
240|      return { body: { success: true as const, draft: result.draft } };"
}
